const input = $json;
const title = String(input.title || '').trim();
const excerpt = String(input.excerpt || '').trim();
const content = String(input.content || '').trim();
const category = String(input.category || '').trim();
const sourceUrl = String(input.source_url || '').trim();

const draftBlock = [
  `Title: ${title || '[empty]'}`,
  `Category: ${category || '[empty]'}`,
  `Summary: ${excerpt || '[empty]'}`,
  `Reference URL: ${sourceUrl || '[none]'}`,
  'Content:',
  content || '[empty]'
].join('\n');

const searchPrompt = [
  'Search The Straits Times for stories similar to this draft article.',
  'Return ONLY valid JSON with this exact shape:',
  '{',
  '  "search_summary": "",',
  '  "matched_articles": [',
  '    {',
  '      "title": "",',
  '      "url": "",',
  '      "relevance_note": ""',
  '    }',
  '  ]',
  '}',
  '',
  'Rules:',
  '- Search only The Straits Times.',
  '- Return up to 5 matched articles.',
  '- Pick stories that are genuinely similar to the draft topic or claims.',
  '',
  'Draft article:',
  draftBlock
].join('\n');

return [{
  json: {
    ...input,
    title,
    excerpt,
    content,
    category,
    source_url: sourceUrl,
    draft_block: draftBlock,
    search_prompt: searchPrompt
  }
}];

