={{ ({
  model: 'gpt-5-mini',
  reasoning: { effort: 'low' },
  tools: [
    {
      type: 'web_search',
      filters: {
        allowed_domains: ['straitstimes.com', 'www.straitstimes.com']
      }
    }
  ],
  tool_choice: 'auto',
  text: {
    format: {
      type: 'json_schema',
      name: 'sharedspace_st_search',
      strict: true,
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          search_summary: { type: 'string' },
          matched_articles: {
            type: 'array',
            items: {
              type: 'object',
              additionalProperties: false,
              properties: {
                title: { type: 'string' },
                url: { type: 'string' },
                relevance_note: { type: 'string' }
              },
              required: ['title', 'url', 'relevance_note']
            }
          }
        },
        required: ['search_summary', 'matched_articles']
      }
    }
  },
  input: [
    {
      role: 'system',
      content: 'Return JSON only. Search Straits Times for similar stories based on the draft article provided by the user.'
    },
    {
      role: 'user',
      content: $json.search_prompt
    }
  ]
}) }}

