const raw = $json.output_text || $json.output?.find((item) => item.type === 'message')?.content?.find((part) => part.type === 'output_text')?.text || '{}';
const cleaned = String(raw).replace(/```json|```/gi, '').trim();
let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  parsed = { search_summary: 'Search response could not be parsed.', matched_articles: [] };
}

const matchedArticles = Array.isArray(parsed.matched_articles)
  ? parsed.matched_articles.slice(0, 5).map((article) => ({
      title: String(article.title || ''),
      url: String(article.url || ''),
      relevance_note: String(article.relevance_note || '')
    }))
  : [];

const upstream = $items('Build Draft Context', 0, 0)?.json || {};
const matchesText = matchedArticles.length
  ? matchedArticles.map((article, index) => `${index + 1}. ${article.title}\nURL: ${article.url}\nWhy relevant: ${article.relevance_note}`).join('\n\n')
  : 'No strong Straits Times match found.';

const comparePrompt = [
  'You are a verification assistant for SharedSpace.',
  'Compare the draft article against the matched Straits Times stories below.',
  'Return ONLY valid JSON.',
  '',
  'Return this exact schema:',
  '{',
  '  "trust_score": 0,',
  '  "summary": "",',
  '  "verdict": "",',
  '  "metrics": {',
  '    "factual_accuracy": 0,',
  '    "source_quality": 0,',
  '    "bias_detection": 0,',
  '    "logical_consistency": 0,',
  '    "completeness": 0',
  '  },',
  '  "source_label": ""',
  '}',
  '',
  'Rules:',
  '- All scores must be integers from 0 to 100.',
  '- Use the matched Straits Times stories as the comparison base.',
  '- If no strong match was found, lower source_quality and explain that clearly.',
  '- Never say the draft is missing unless the draft block below is actually empty.',
  '',
  'Draft article:',
  upstream.draft_block || '[missing draft block]',
  '',
  'Matched Straits Times stories:',
  matchesText
].join('\n');

return [{
  json: {
    ...upstream,
    matched_articles: matchedArticles,
    search_summary: String(parsed.search_summary || ''),
    compare_prompt: comparePrompt
  }
}];

